import React, { useEffect, useState } from 'react';
import { FaPhone, FaMapMarkerAlt, FaClock } from 'react-icons/fa';
import './footer.css';

const Footer = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [lastScrollPos, setLastScrollPos] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollPos = window.scrollY;
      const scrollDirection = currentScrollPos > lastScrollPos ? 'down' : 'up';
      setLastScrollPos(currentScrollPos);

      const pageBottom = window.innerHeight + currentScrollPos;
      const documentHeight = document.documentElement.scrollHeight;
      const threshold = 100; // pixels from bottom

      // Show when scrolling down near bottom
      if (scrollDirection === 'down' && (documentHeight - pageBottom < threshold)) {
        setIsVisible(true);
      } 
      // Hide when scrolling up
      else if (scrollDirection === 'up') {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollPos]);

  return (
    <footer className={`footer ${isVisible ? 'visible' : ''}`}>
      <div className="footer-content">
        <div className="footer-section">
          <h3>Hotel Shyam</h3>
          <p>Authentic flavors since 1985</p>
        </div>

        <div className="footer-section">
          <h3>Contact</h3>
          <p><FaPhone /> +91 9876543210</p>
          <p><FaMapMarkerAlt /> 123 Food Street, Mumbai</p>
          <p><FaClock /> Open: 11AM - 11PM</p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
